"use strict";(self.webpackChunkcallvault_docs=self.webpackChunkcallvault_docs||[]).push([["875"],{51313(e){e.exports=JSON.parse('{"tag":{"label":"developers","permalink":"/tags/developers","allTagsPath":"/tags","count":7,"items":[{"id":"developers/authentication","title":"Access keys","description":"Make a read-only CallVault access key, choose what it may read and when it stops, send it as a Bearer token, and show it again within 10 minutes of signing in.","permalink":"/developers/authentication"},{"id":"developers/assistants","title":"Assistants (MCP)","description":"Connect Claude, ChatGPT, Claude Code or Cursor to CallVault over MCP, choose what it may read on the consent page, and see the six read-only tools an assistant can use. Audio stays off unless you tick it.","permalink":"/developers/assistants"},{"id":"developers/index","title":"CallVault for developers","description":"What your own script, an assistant such as Claude or ChatGPT, or your own server can read from your CallVault account, the addresses they use and what each plan allows. Everything outside CallVault is read only.","permalink":"/developers"},{"id":"developers/changelog","title":"Developer changelog","description":"Changes to CallVault\'s API, MCP server, webhooks and two-step sign-in, newest first, with the date each reached the live service.","permalink":"/developers/changelog"},{"id":"developers/api","title":"The CallVault API","description":"Read your CallVault recordings, notes, audio links, plan and household over REST with an access key: every route with a curl example, the response envelope, errors, pages, rate limits and the OpenAPI document.","permalink":"/developers/api"},{"id":"developers/two-step-sign-in","title":"Two-step sign-in","description":"Turn on two-step sign-in for CallVault on the phone or in the web library: a six-digit authenticator code after Google, ten single-use recovery codes, an optional seven-day remembered phone or browser, and what to do when a phone is lost.","permalink":"/developers/two-step-sign-in"},{"id":"developers/webhooks","title":"Webhooks","description":"CallVault sends your server a signed POST when a recording is added or its audio finishes uploading. Every event with a sample payload, signature checks in Node and Python, a message to test against, and the retry schedule.","permalink":"/developers/webhooks"}],"unlisted":false}}')}}]);